// [...]}` alone (`tbh-session-view-serve`'s `materialized_fold.rs`, the
// `select_genesis_history` call), while the anchored rung serves the full folded state. A
// schema-validating client resuming with `{"history": "snapshot"}` against the real fold
// therefore sees the other required members missing. The fix is a serving change in the
// #208/#14653 lane (serialize the `SessionViewState` the genesis path already folds, as
// the anchored path does) plus its own RED against the real fold; it is not a shape change
// here, because SS4.9.1 ratifies this shape.
type SnapshotState struct {
	// The running foreground turn; `null` when none is running.
	ActiveTurn *TurnRef `json:"activeTurn,omitempty"`
	// The effective approval mode at this cursor — the same object the `Session` carries
	// (tdd SS2.4, SS5.12).
	ApprovalMode EffectiveApprovalModeState `json:"approvalMode"`
	// Latest branch observation; `null` when no fact has landed.
	Branch *BranchState `json:"branch,omitempty"`
	// The latest `(windowTokens, usedTokens, pressure)` triple. SS4.9.1 says "`null`/absent"
	// and SS4.9.2's worked example OMITS the member; the binary omits it too, so this is the
	// absent arm — the four siblings above are present-null in the same frame. INV-017
	// admits one or the other, never both; escalated under #22785.
	ContextUsage *ContextUsage `json:"contextUsage,omitempty"`
	// Latest effective model; `null` when no fact has landed.
	EffectiveModel *EffectiveModel `json:"effectiveModel,omitempty"`
	// Latest goal block; `null` when no fact has landed.
	Goal *Goal `json:"goal,omitempty"`
	// Every item, in first-opened order, each at its latest revision at the snapshot cursor.
	// One schema per kind, shared with the notification item object — which is what makes
	// snapshot+suffix a pure splice (tdd SS4.9.1).
	Items []Item `json:"items"`
	// The settled canonical session name; `null` when the session was never named (#27598, tdd
	// SS4.9.1 / SS2.14). Folds the same durable `session/nameChanged` record `Session.name`
	// reports.
	Name *string `json:"name,omitempty"`
	// The pending-approval half of the pending set.
	PendingApprovals []PendingApprovalPointer `json:"pendingApprovals"`
	// The pending-user-input half of the pending set.
	PendingUserInputs []PendingUserInputPointer `json:"pendingUserInputs"`
	// Admitted-but-not-launched submits, in launch order (tdd SS3.1.4).
	QueuedTurns []TurnRef `json:"queuedTurns"`
	// The latest session-default reasoning effort with its source; ABSENT until a set lands
	// (tdd SS4.9.1 `reasoningEffort`, ADR 31255 D1 — the `contextUsage` absent arm, never
	// present-null).
	ReasoningEffort *ReasoningEffortState `json:"reasoningEffort,omitempty"`
	// Latest todo list; `null` when no fact has landed.
	TodoList *TodoListState `json:"todoList,omitempty"`
	// The `cumulative` block of the last `session/tokenUsage` event; zeroes when none (tdd
	// SS4.9.1).
	TokenUsage CumulativeTokenUsage `json:"tokenUsage"`
	// Completed-turn count at this cursor.
	TurnCount int64 `json:"turnCount"`
}

// SourceRange The inclusive raw-record range a durable-sourced view event folded from (tdd SS4.2) —
