// ViewGapParams `view/gap` params (spec 208 SS4.8, FM-001): push delivery dropped events, and this names
// the hole. The bracket is deferred (D-16487-2): it flushes at the subscription's next
// ACCEPTED delivery, never at enqueue time, so `next` always names an event whose own
// delivery is proven. A run of consecutive undelivered events coalesces into one bracket
// keeping the FIRST range's `after` (D-16487-1). The gap rides the protected reserved
// queue, so no wire-interleaving order against neighbouring deliveries is promised — the
// cursors carry the semantics (INV-002, D-16487-3). On receipt a client may take either
// sanctioned recovery (D-030, FR-013): splice-fill — buffer live events at cursors >=
// `next`, page `(after, next)` forward, discard the overlap, splice — or re-anchor
// through the anchored read surface. The server requires neither, cannot distinguish
// clients by their choice, and holds no partial-fill state.
type ViewGapParams struct {
	// The last cursor delivered before the hole — the exclusive lower bound of the
	// undelivered range. An **opaque** view cursor: clients relay it, never parse it (tdd
	// SS4.1).
	After string `json:"after"`
	// The first cursor delivered after the hole — the exclusive upper bound of the
	// undelivered range, and the position delivery continues from. An **opaque** view cursor:
	// clients relay it, never parse it (tdd SS4.1).
	Next string `json:"next"`
	// The session whose subscription dropped events.
	SessionID string `json:"sessionId"`
}

